package yagen.waitmydawn.kb.service;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import yagen.waitmydawn.kb.model.*;import yagen.waitmydawn.kb.config.*;import static org.junit.jupiter.api.Assertions.*;
class RuntimeAttributesTest {
 @TempDir Path temp;private final ObjectMapper json=new ObjectMapper();
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(ints={1,2,3}) void attributesAreValidatedImportedSearchableAndKeepTheirRealSource(int capabilityVersion)throws Exception {
  var pack=RuntimeBuildFixtures.create(temp.resolve("MKB-Export"),List.of(),"neoforge","1.21.1");var descriptor=(ObjectNode)json.readTree(pack.resolve("snapshot.json").toFile());
  var item=json.readTree("{\"id\":\"minecraft:stone\",\"schemaVersion\":1,\"context\":\"SERVER_DEFAULT_STACK\",\"maxStackSize\":64,\"maxDamage\":0,\"modifiers\":[]}");
  var entity=json.readTree("{\"id\":\"minecraft:pig\",\"schemaVersion\":1,\"context\":\"SERVER_DEFAULT_INSTANCE\",\"attributes\":[{\"attribute\":\"minecraft:generic.max_health\",\"base\":10,\"effective\":12,\"modifiers\":[]}]}");
  for(String category:List.of("item_attributes","entity_attributes","entity_state_attributes","loot_entrypoints")){var row=category.equals("loot_entrypoints")?json.readTree("{\"id\":\"mkb_export:entity/minecraft/pig\",\"source\":\"minecraft:pig\",\"sourceKind\":\"entity\",\"lootTable\":\"minecraft:entities/pig\",\"relation\":\"DEFAULT_DECLARATION\"}"):category.equals("item_attributes")?item.deepCopy():entity.deepCopy();if(category.equals("entity_state_attributes")){((ObjectNode)row).put("context","SERVER_ENTITY_SAMPLE");((ObjectNode)row).put("stateKey","default");}var payload=json.createObjectNode().put("format","mkb-data").put("schemaVersion",1).put("category",category).put("authoritative",true).put("capabilityVersion",1);payload.putArray("records").add(row);Path file=pack.resolve("data/"+category+".json");if(category.equals("entity_attributes")){
    payload.put("capabilityVersion",capabilityVersion);
    if(capabilityVersion>=2)((ObjectNode)row).put("context","SERVER_LOADED_INSTANCE").put("defaultsOnly",false);
    if(capabilityVersion==3){((ObjectNode)row).put("context","SERVER_INITIALIZED_TICK_SAMPLE").put("sampleTicks",1).put("worldTickAdvanced",true).put("initialization","LOADER_FINALIZE_SPAWN");((ObjectNode)row.path("attributes").get(0)).put("entityTypeBase",10).put("registryDefault",20);}
   }
   json.writeValue(file.toFile(),payload);((ObjectNode)descriptor.path("categories")).putObject(category).put("status","COMPLETE").put("total",1).put("succeeded",1).put("transparent",0).put("unsupported",0).put("failed",0).put("file","data/"+category+".json").put("sha256",ArtifactFingerprint.sha256(file));}
  json.writeValue(pack.resolve("snapshot.json").toFile(),descriptor);
  Files.createDirectories(temp.resolve("database"));var config=AppConfig.forIsolatedRun(false).forBuildTarget(temp.resolve("database"));var db=new DatabaseBuilder(config);db.initDatabase();
  try(var embedding=new EmbeddingService(null)){new KnowledgeBuilder(config,db,embedding).build(new BuildRequest(List.of(BuildRequest.Source.of(BuildRequest.Kind.DOCUMENT_DIRECTORY,pack.toString()))),null);String profile=RuntimeKnowledgeStore.active(db);assertEquals(1,new RuntimeCatalog(db).page(profile,RuntimeCatalog.Kind.LOOT_SOURCES,"pig","",0,50).total());String text=RuntimeAttributes.details(db,profile,"minecraft:pig","default");assertTrue(text.contains("基础值 10"));assertTrue(text.contains("有效值 12"));
   if(capabilityVersion==3){var stored=new RuntimeStructuredQuery(db,profile).get("entity_attributes","minecraft:pig").rows().get(0).data();assertEquals(1,stored.path("sampleTicks").asInt());assertEquals("LOADER_FINALIZE_SPAWN",stored.path("initialization").asText());assertEquals(10,stored.path("attributes").get(0).path("entityTypeBase").asInt());assertFalse(text.contains("默认构造实例未执行真实生成钩子"));}
assertFalse(RuntimeAttributes.evidence(db,List.of("minecraft:pig"),"猪的生命值是多少").isEmpty());try(var c=db.getConnection();var st=c.createStatement();var counts=st.executeQuery("SELECT COUNT(*) FROM rag_vectors WHERE chunk_type='runtime_entity_state_attributes'")){counts.next();assertEquals(0,counts.getInt(1));}new SourceLifecycleStore(db).execute("DELETE FROM rag_build_metadata WHERE name=?","runtime_text_policy:"+profile);new KnowledgeBuilder(config,db,embedding).build(new BuildRequest(List.of(BuildRequest.Source.of(BuildRequest.Kind.DOCUMENT_DIRECTORY,pack.toString())),BuildRequest.Mode.APPEND),null);assertEquals(List.of("3"),new SourceLifecycleStore(db).strings("SELECT meta_value FROM rag_build_metadata WHERE name=?","runtime_text_policy:"+profile));assertTrue(RuntimeAttributes.details(db,profile,"minecraft:stone","default").contains("64"));try(var c=db.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT location FROM rag_document WHERE title='游戏快照 · 实体属性'")){assertFalse(r.next());assertFalse(new RuntimeStructuredQuery(db,profile).get("entity_attributes","minecraft:pig").rows().isEmpty());}}
  finally{db.shutdown();}
 }
 @Test void invalidNumericsAndFutureVersionsAreRejected()throws Exception{var row=(ObjectNode)json.readTree("{\"id\":\"minecraft:pig\",\"schemaVersion\":1,\"context\":\"SERVER_DEFAULT_INSTANCE\",\"attributes\":[{\"attribute\":\"minecraft:generic.max_health\",\"base\":10,\"effective\":\"unknown\"}]}");assertThrows(java.io.IOException.class,()->RuntimeAttributes.validate("entity_attributes",row));row.put("schemaVersion",2);assertThrows(java.io.IOException.class,()->RuntimeAttributes.validate("entity_attributes",row));}
}
